return new { scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>new {path=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).path,roots=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).GetRootGameObjects().Select(o=>o.name).ToArray()}).ToArray(), hud=UnityEngine.Object.FindObjectsByType<Cheon.Prototype.MountainPass.PassHud>(FindObjectsSortMode.None).Select(h=>new {path=UnityEditor.AnimationUtility.CalculateTransformPath(h.transform,null),scene=h.gameObject.scene.path}).ToArray(),canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Select(c=>new {c.name,scene=c.gameObject.scene.path}).ToArray()};
